func buildWorldBraille(wCells, hCells int, style tui.Style) tui.Image {
	pixW := wCells * 2
	pixH := hCells * 4
	if pixW <= 0 || pixH <= 0 {
		return nil
	}

	data := make([][]bool, pixH)
	for i := range data {
		data[i] = make([]bool, pixW)
	}

	const mapAspect = 2.0
	screenAspect := float64(pixW) / float64(pixH)

	var scale, offsetX, offsetY float64
	if screenAspect > mapAspect {
		scale = float64(pixH) / 180.0
		offsetX = (float64(pixW) - 360.0*scale) / 2.0
	} else {
		scale = float64(pixW) / 360.0
		offsetY = (float64(pixH) - 180.0*scale) / 2.0
	}

	for _, p := range mapData {
		x := int(math.Round((p.Lon+180)*scale + offsetX))
		y := int(math.Round((90-p.Lat)*scale + offsetY))
		if x >= 0 && x < pixW && y >= 0 && y < pixH {
			data[y][x] = true
		}
	}

	var iw tui.Image
	iw = iw.LoadBraille(data, style)
	return iw
}

type coord struct {
	Lat, Lon float64
}

func main() {
	wnd := tui.NewWindow()

	style := tui.FrGreen

	wnd.RegisterResizeHandler(func(w, h int) {
		wnd.SetContent(tui.NewFrame(buildWorldBraille(w-4, h-2, tui.FrGreen)))
	})

	img := buildWorldBraille(wnd.Width()-4, wnd.Height()-2, style)
	wnd.SetContent(tui.NewFrame(img).WithTitle(tui.Title{Text: "TUI Compose World Map", Style: tui.FrYellow, Pos: tui.TitleTopCenter}).Double())

	wnd.Run()
}
